import {
  Component,
  EventEmitter,
  Input,
  Output,
  signal,
  OnChanges,
  SimpleChanges,
  inject,
  DestroyRef,
  AfterViewInit,
  OnDestroy,
  ElementRef,
  ViewChild,
  NgZone,
  ChangeDetectorRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { catchError, of } from 'rxjs';

export interface CoordenadasValue {
  altitud: number | null;
  latitud: number | null;
  longitud: number | null;
  latitudGrados?: number | null;
  latitudMinutos?: number | null;
  latitudSegundos?: number | null;
  longitudGrados?: number | null;
  longitudMinutos?: number | null;
  longitudSegundos?: number | null;
}

interface NominatimResult {
  lat: string;
  lon: string;
  display_name: string;
}

export interface LeafletMapInstance {
  setView(center: [number, number], zoom: number): LeafletMapInstance;
  on(event: string, fn: (e: { latlng: { lat: number; lng: number } }) => void): void;
  invalidateSize(): void;
  remove(): void;
}

export interface LeafletMarkerInstance {
  addTo(map: LeafletMapInstance): LeafletMarkerInstance;
  setLatLng(latlng: [number, number] | { lat: number; lng: number }): LeafletMarkerInstance;
  on(event: string, fn: (e: { target: { getLatLng: () => { lat: number; lng: number } } }) => void): void;
  remove(): void;
}

export interface LeafletGlobal {
  map(element: HTMLElement): LeafletMapInstance;
  tileLayer(url: string, options: Record<string, string | number>): { addTo(map: LeafletMapInstance): void };
  marker(coords: [number, number] | { lat: number; lng: number }, options?: Record<string, boolean>): LeafletMarkerInstance;
}

declare global {
  interface Window {
    L?: LeafletGlobal;
  }
}

@Component({
  selector: 'app-coordenadas-picker',
  imports: [CommonModule, FormsModule],
  templateUrl: './coordenadas-picker.component.html',
  styleUrl: './coordenadas-picker.component.scss',
})
export class CoordenadasPickerComponent implements OnChanges, AfterViewInit, OnDestroy {
  private readonly http = inject(HttpClient);
  private readonly destroyRef = inject(DestroyRef);
  private readonly ngZone = inject(NgZone);
  private readonly cdr = inject(ChangeDetectorRef);

  @ViewChild('mapContainer') mapContainerRef?: ElementRef<HTMLElement>;

  @Input() altitud: number | null = null;
  @Input() latitud: number | null = null;
  @Input() longitud: number | null = null;
  @Input() latitudGrados: number | null = null;
  @Input() latitudMinutos: number | null = null;
  @Input() latitudSegundos: number | null = null;
  @Input() longitudGrados: number | null = null;
  @Input() longitudMinutos: number | null = null;
  @Input() longitudSegundos: number | null = null;
  @Input() readonly = false;
  @Output() readonly coordenadasChange = new EventEmitter<CoordenadasValue>();

  mapSearchQuery = signal('Baja California, México');
  errorMessage = signal<string | null>(null);
  mapLat = signal<number>(32.5149);
  mapLng = signal<number>(-117.0382);

  private mapInstance: LeafletMapInstance | null = null;
  private markerInstance: LeafletMarkerInstance | null = null;

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['altitud']) {
      this.altitud = changes['altitud'].currentValue;
    }
    if (
      changes['latitud'] ||
      changes['longitud'] ||
      changes['latitudGrados'] ||
      changes['latitudMinutos'] ||
      changes['latitudSegundos'] ||
      changes['longitudGrados'] ||
      changes['longitudMinutos'] ||
      changes['longitudSegundos']
    ) {
      this.syncCoordinatesToMapState();
      this.updateMapPosition();
    }
    if (changes['readonly'] && !changes['readonly'].firstChange) {
      this.destroyMap();
      setTimeout(() => this.initLeafletMap(), 50);
    }
  }

  ngAfterViewInit(): void {
    this.syncCoordinatesToMapState();
    setTimeout(() => this.initLeafletMap(), 100);
  }

  ngOnDestroy(): void {
    this.destroyMap();
  }

  private toNumberOrNull(value: unknown): number | null {
    if (value === null || value === undefined || value === '') {
      return null;
    }
    const num = Number(value);
    return Number.isFinite(num) ? num : null;
  }

  private syncCoordinatesToMapState(): void {
    let decLat = this.toNumberOrNull(this.latitud);
    let decLng = this.toNumberOrNull(this.longitud);

    if (
      decLat === null &&
      (this.latitudGrados != null || this.latitudMinutos != null || this.latitudSegundos != null)
    ) {
      decLat = this.dmsToDecimal(
        this.toNumberOrNull(this.latitudGrados),
        this.toNumberOrNull(this.latitudMinutos),
        this.toNumberOrNull(this.latitudSegundos),
      );
    }
    if (
      decLng === null &&
      (this.longitudGrados != null || this.longitudMinutos != null || this.longitudSegundos != null)
    ) {
      decLng = this.dmsToDecimal(
        this.toNumberOrNull(this.longitudGrados),
        this.toNumberOrNull(this.longitudMinutos),
        this.toNumberOrNull(this.longitudSegundos),
      );
      if (decLng !== null) decLng = -Math.abs(decLng);
    }

    if (decLat !== null) {
      this.latitud = decLat;
    }
    if (decLng !== null) {
      this.longitud = decLng;
    }

    if (decLat !== null && decLng !== null) {
      this.mapLat.set(decLat);
      this.mapLng.set(decLng);
    }
  }

  hasValidCoordinates(): boolean {
    const lat =
      this.toNumberOrNull(this.latitud) ??
      this.dmsToDecimal(
        this.toNumberOrNull(this.latitudGrados),
        this.toNumberOrNull(this.latitudMinutos),
        this.toNumberOrNull(this.latitudSegundos),
      );
    const lng =
      this.toNumberOrNull(this.longitud) ??
      this.dmsToDecimal(
        this.toNumberOrNull(this.longitudGrados),
        this.toNumberOrNull(this.longitudMinutos),
        this.toNumberOrNull(this.longitudSegundos),
      );
    return (
      lat !== null &&
      lat !== 0 &&
      lat >= -90 &&
      lat <= 90 &&
      lng !== null &&
      lng !== 0 &&
      Math.abs(lng) <= 180
    );
  }

  formatCoordenadasSummary(): string {
    const parts: string[] = [];
    const lat = this.toNumberOrNull(this.latitud);
    const lng = this.toNumberOrNull(this.longitud);
    const latGrados = this.toNumberOrNull(this.latitudGrados);
    const lngGrados = this.toNumberOrNull(this.longitudGrados);
    const altitud = this.toNumberOrNull(this.altitud);

    if (lat !== null) {
      parts.push(`Lat: ${lat.toFixed(6)}°`);
    } else if (latGrados !== null) {
      parts.push(
        `Lat: ${latGrados}° ${this.toNumberOrNull(this.latitudMinutos) ?? 0}' ${this.toNumberOrNull(this.latitudSegundos) ?? 0}"`,
      );
    }
    if (lng !== null) {
      parts.push(`Long: ${lng.toFixed(6)}°`);
    } else if (lngGrados !== null) {
      parts.push(
        `Long: ${lngGrados}° ${this.toNumberOrNull(this.longitudMinutos) ?? 0}' ${this.toNumberOrNull(this.longitudSegundos) ?? 0}"`,
      );
    }
    if (altitud !== null) {
      parts.push(`Alt: ${altitud} msnm`);
    }
    return parts.length > 0 ? parts.join(' | ') : 'Sin coordenadas registradas';
  }

  onFieldChange(): void {
    const lat = this.toNumberOrNull(this.latitud);
    const lng = this.toNumberOrNull(this.longitud);
    if (lat !== null && lng !== null) {
      this.mapLat.set(lat);
      this.mapLng.set(lng);
    }
    this.updateMapPosition();
    this.emitValues();
  }

  private updateMapPosition(): void {
    if (this.mapInstance && window.L) {
      const lat = this.mapLat();
      const lng = this.mapLng();
      const hasCoords = this.hasValidCoordinates();

      if (hasCoords) {
        this.mapInstance.setView([lat, lng], 13);
        if (this.markerInstance) {
          this.markerInstance.setLatLng([lat, lng]);
        } else {
          const isDraggable = !this.readonly;
          this.markerInstance = window.L.marker([lat, lng], { draggable: isDraggable }).addTo(this.mapInstance);
          this.attachMarkerEvents();
        }
      } else {
        if (this.markerInstance) {
          this.markerInstance.remove();
          this.markerInstance = null;
        }
        this.mapInstance.setView([lat, lng], 8);
      }
    }
  }

  useCurrentLocation(): void {
    if (this.readonly) return;
    this.errorMessage.set(null);
    if (!navigator.geolocation) {
      this.errorMessage.set('La geolocalización no está disponible en este navegador.');
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        this.ngZone.run(() => {
          const lat = pos.coords.latitude;
          const lng = pos.coords.longitude;
          this.setCoordinatesFromDecimal(lat, lng);
        });
      },
      (err) => {
        this.ngZone.run(() => {
          this.errorMessage.set(`No se pudo obtener la ubicación: ${err.message}`);
        });
      }
    );
  }

  searchLocation(): void {
    if (this.readonly) return;
    const query = this.mapSearchQuery().trim();
    if (!query) return;

    this.errorMessage.set(null);
    const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}`;

    this.http.get<NominatimResult[]>(url)
      .pipe(
        takeUntilDestroyed(this.destroyRef),
        catchError(() => {
          this.errorMessage.set('Error de red al buscar la ubicación.');
          return of([]);
        })
      )
      .subscribe((data) => {
        this.ngZone.run(() => {
          if (data && data.length > 0) {
            const first = data[0];
            const newLat = parseFloat(first.lat);
            const newLng = parseFloat(first.lon);
            this.setCoordinatesFromDecimal(newLat, newLng);
          } else {
            this.errorMessage.set('No se encontraron resultados para la búsqueda.');
          }
        });
      });
  }

  private setCoordinatesFromDecimal(lat: number, lng: number): void {
    this.latitud = lat;
    this.longitud = lng;
    this.mapLat.set(lat);
    this.mapLng.set(lng);

    const latDms = this.decimalToDms(lat);
    const lngDms = this.decimalToDms(Math.abs(lng));

    this.latitudGrados = latDms.grados;
    this.latitudMinutos = latDms.minutos;
    this.latitudSegundos = latDms.segundos;
    this.longitudGrados = lngDms.grados;
    this.longitudMinutos = lngDms.minutos;
    this.longitudSegundos = lngDms.segundos;

    this.updateMapPosition();
    this.emitValues();
    this.cdr.markForCheck();
    this.fetchAltitude(lat, lng);
  }

  private fetchAltitude(lat: number, lng: number): void {
    const url = `https://api.open-meteo.com/v1/elevation?latitude=${lat}&longitude=${lng}`;
    this.http
      .get<{ elevation?: number[] }>(url)
      .pipe(
        takeUntilDestroyed(this.destroyRef),
        catchError(() => of(null)),
      )
      .subscribe((res) => {
        const elevation = res?.elevation;
        if (Array.isArray(elevation) && elevation.length > 0 && typeof elevation[0] === 'number') {
          this.ngZone.run(() => {
            this.altitud = Math.round(elevation[0]);
            this.cdr.markForCheck();
            this.emitValues();
          });
        }
      });
  }

  private emitValues(): void {
    const lat = this.toNumberOrNull(this.latitud);
    const lng = this.toNumberOrNull(this.longitud);
    const latDms = lat !== null ? this.decimalToDms(lat) : null;
    const lngDms = lng !== null ? this.decimalToDms(Math.abs(lng)) : null;

    this.coordenadasChange.emit({
      altitud: this.toNumberOrNull(this.altitud),
      latitud: lat,
      longitud: lng,
      latitudGrados: latDms?.grados ?? this.toNumberOrNull(this.latitudGrados),
      latitudMinutos: latDms?.minutos ?? this.toNumberOrNull(this.latitudMinutos),
      latitudSegundos: latDms?.segundos ?? this.toNumberOrNull(this.latitudSegundos),
      longitudGrados: lngDms?.grados ?? this.toNumberOrNull(this.longitudGrados),
      longitudMinutos: lngDms?.minutos ?? this.toNumberOrNull(this.longitudMinutos),
      longitudSegundos: lngDms?.segundos ?? this.toNumberOrNull(this.longitudSegundos),
    });
  }

  private dmsToDecimal(g: number | null, m: number | null, s: number | null): number | null {
    if (g === null) return null;
    const val = g + (m ?? 0) / 60 + (s ?? 0) / 3600;
    return isNaN(val) ? null : val;
  }

  private decimalToDms(val: number): { grados: number; minutos: number; segundos: number } {
    const absVal = Math.abs(val);
    const grados = Math.floor(absVal);
    const minFloat = (absVal - grados) * 60;
    const minutos = Math.floor(minFloat);
    const segundos = Math.round((minFloat - minutos) * 60);
    return { grados, minutos, segundos };
  }

  private destroyMap(): void {
    if (this.mapInstance) {
      this.mapInstance.remove();
      this.mapInstance = null;
      this.markerInstance = null;
    }
  }

  private initLeafletMap(): void {
    if (typeof window === 'undefined') return;

    const container = this.mapContainerRef?.nativeElement;
    if (!container) return;

    if (!window.L) {
      if (!document.getElementById('leaflet-css')) {
        const link = document.createElement('link');
        link.id = 'leaflet-css';
        link.rel = 'stylesheet';
        link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
        document.head.appendChild(link);
      }

      const script = document.createElement('script');
      script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
      script.onload = () => this.renderLeafletMap(container);
      script.onerror = () => {
        this.errorMessage.set('No se pudo cargar la librería de mapa Leaflet.');
      };
      document.head.appendChild(script);
    } else {
      this.renderLeafletMap(container);
    }
  }

  private renderLeafletMap(container: HTMLElement): void {
    const L = window.L;
    if (!L) return;

    this.destroyMap();

    const hasCoords = this.hasValidCoordinates();
    const lat = this.mapLat();
    const lng = this.mapLng();
    const zoom = hasCoords ? 13 : 8;
    this.mapInstance = L.map(container).setView([lat, lng], zoom);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '© OpenStreetMap',
    }).addTo(this.mapInstance);

    const isDraggable = !this.readonly;
    if (hasCoords) {
      this.markerInstance = L.marker([lat, lng], { draggable: isDraggable }).addTo(this.mapInstance);
      this.attachMarkerEvents();
    }

    if (isDraggable) {
      this.mapInstance.on('click', (event) => {
        this.ngZone.run(() => {
          const position = event.latlng;
          if (!this.markerInstance) {
            this.markerInstance = L.marker([position.lat, position.lng], { draggable: true }).addTo(this.mapInstance!);
            this.attachMarkerEvents();
          } else {
            this.markerInstance.setLatLng([position.lat, position.lng]);
          }
          this.setCoordinatesFromDecimal(position.lat, position.lng);
        });
      });
    }

    setTimeout(() => {
      this.mapInstance?.invalidateSize();
    }, 200);
  }

  private attachMarkerEvents(): void {
    if (!this.markerInstance || this.readonly) return;

    this.markerInstance.on('dragend', (event) => {
      this.ngZone.run(() => {
        const position = event.target.getLatLng();
        this.setCoordinatesFromDecimal(position.lat, position.lng);
      });
    });
  }
}
